#include "fine_sun_sensor.hpp"
#include "kernels.hpp"
#include "sensor_kernels_pybind.hpp"
#include "philox.hpp"
#include <Eigen/Cholesky>
#include <cmath>
#include <string>
namespace py=pybind11;namespace omni::hardware::sensors {
namespace {template<std::size_t N>std::array<double,N> read(py::handle x,const char*n){auto a=py::array_t<double,py::array::c_style|py::array::forcecast>::ensure(x);if(!a||a.ndim()!=1||a.shape(0)!=static_cast<py::ssize_t>(N))throw py::value_error(std::string(n)+" has an invalid shape");std::array<double,N>r{};auto v=a.unchecked<1>();for(std::size_t i=0;i<N;++i)r[i]=v(static_cast<py::ssize_t>(i));return r;}py::array_t<double> arr2(const std::array<double,2>&v){py::array_t<double>a(2);auto o=a.mutable_unchecked<1>();o(0)=v[0];o(1)=v[1];return a;}py::array_t<double> arr23(const std::array<std::array<double,3>,2>&m){py::array_t<double>a({2,3});auto o=a.mutable_unchecked<2>();for(int i=0;i<2;++i)for(int j=0;j<3;++j)o(i,j)=m[i][j];return a;} }
FineSunSensor::FineSunSensor(py::handle p,py::handle q,py::handle m,py::handle n,py::handle b,py::handle f):position(kernels::read_vector3(p,"position")),orientation(kernels::normalize(kernels::read_quaternion(q,"orientation"))),misalignment(kernels::normalize(kernels::read_quaternion(m,"misalignment"))),bias(read<2>(b,"bias")),fov_half_angles(read<2>(f,"fov_half_angles")){
 auto a=py::array_t<double,py::array::c_style|py::array::forcecast>::ensure(n);if(!a||a.ndim()!=2||a.shape(0)!=2||a.shape(1)!=2)throw py::value_error("noise must be 2x2");auto v=a.unchecked<2>();for(int i=0;i<2;++i)for(int j=0;j<2;++j)noise[i][j]=v(i,j);
 Eigen::Matrix2d cov;cov<<noise[0][0],noise[0][1],noise[1][0],noise[1][1];Eigen::LLT<Eigen::Matrix2d> llt(cov);if(llt.info()!=Eigen::Success)throw py::value_error("noise covariance must be positive definite");Eigen::Matrix2d l=llt.matrixL().toDenseMatrix();for(int i=0;i<2;++i)for(int j=0;j<2;++j)noise_cholesky[i][j]=l(i,j);
}
py::array_t<double> FineSunSensor::measure(py::handle s,py::handle q,bool wb,bool wn){V2 z{};if(wn){auto d=omni::helpers::random::standard_normals(seed,random_tick++,0x40000000U,2);z={{d[0],d[1]}};}return arr2(kernels::fine_direction_measurement(read<3>(s,"sun_inertial"),kernels::read_quaternion(q,"attitude"),orientation,misalignment,bias,noise_cholesky,wb,wn,wn?&z:nullptr));}
py::array_t<double> FineSunSensor::noiseless_biasfree_measurement(py::handle s,py::handle q)const{return const_cast<FineSunSensor*>(this)->measure(s,q,false,false);}py::array_t<double> FineSunSensor::noiseless_biased_measurement(py::handle s,py::handle q)const{return const_cast<FineSunSensor*>(this)->measure(s,q,true,false);}py::array_t<double> FineSunSensor::noisy_biasfree_measurement(py::handle s,py::handle q){return measure(s,q,false,true);}py::array_t<double> FineSunSensor::noisy_biased_measurement(py::handle s,py::handle q){return measure(s,q,true,true);}
py::array_t<double> FineSunSensor::jacobian_bias()const{py::array_t<double>a({2,2});auto o=a.mutable_unchecked<2>();o(0,0)=1;o(0,1)=0;o(1,0)=0;o(1,1)=1;return a;}
py::array_t<double> FineSunSensor::jacobian_relative_quaternion(py::handle s,py::handle q,py::handle d)const{return arr23(kernels::fine_sun_attitude_jacobian(read<3>(s,"sun_inertial"),kernels::read_quaternion(q,"attitude"),orientation,misalignment,kernels::read_quaternion(d,"delta_quaternion"),0));}py::array_t<double> FineSunSensor::jacobian_relative_mrp(py::handle s,py::handle q,py::handle d)const{return arr23(kernels::fine_sun_attitude_jacobian(read<3>(s,"sun_inertial"),kernels::read_quaternion(q,"attitude"),orientation,misalignment,kernels::read_vector3(d,"delta_mrp"),1));}py::array_t<double> FineSunSensor::jacobian_relative_angle_vector(py::handle s,py::handle q,py::handle d)const{return arr23(kernels::fine_sun_attitude_jacobian(read<3>(s,"sun_inertial"),kernels::read_quaternion(q,"attitude"),orientation,misalignment,kernels::read_vector3(d,"delta_angle"),2));}
bool FineSunSensor::availability(py::handle s,py::handle q,bool visible)const{return kernels::fine_direction_available(read<3>(s,"sun_inertial"),kernels::read_quaternion(q,"attitude"),orientation,misalignment,fov_half_angles,enabled,visible);}
py::array_t<double> FineSunSensor::fisher_information_matrix(py::handle s,py::handle q,bool visible)const{std::array<std::array<double,3>,3> z{};if(availability(s,q,visible)){auto sun=read<3>(s,"sun_inertial");auto body=kernels::rotate_inertial_to_sensor(sun,kernels::read_quaternion(q,"attitude"),orientation,misalignment);z=kernels::fine_sun_fisher_information({{std::atan2(body[0],body[2]),std::atan2(body[1],body[2])}},noise,orientation,misalignment);}py::array_t<double>out({3,3});auto o=out.mutable_unchecked<2>();for(int i=0;i<3;++i)for(int j=0;j<3;++j)o(i,j)=z[i][j];return out;}
}
